isdefined(G, :G1DiffusionScalarFieldV1) || error("G1 declaration symbols unavailable after include")
isdefined(G, :G2MBChartMapV1) || error("G2 declaration symbols unavailable after include")
q(id, v) = G.QualifiedRefV1(id, v)
sha(path) = bytes2hex(SHA.sha256(read(path)))
write_record(path, body) = open(joinpath(OUT, path), "w") do io; print(io, body); end
function g1_inputs()
    z=G.UnitSignature((0,0,0,0,0,0,0)); sc=G.PhysicalType(:scalar_field,0,3,G.TemporalTypeV1(G.static_time),z); gr=G.PhysicalType(:vector_field,1,3,G.TemporalTypeV1(G.static_time),G.UnitSignature((-1,0,0,0,0,0,0))); ff=G.PhysicalType(:scalar_field,0,3,G.TemporalTypeV1(G.static_time),G.UnitSignature((-2,0,0,0,0,0,0))); src=q("fusionconceptai://source/review-r1-g1","v1")
    u=G.G1DiffusionScalarFieldV1("u",sc,src;source_expression="u=x"); ke=G.G1DiffusionDiagonalAffineKFieldV1("Kexpr";base_diag=(2,3,4),slope_diag=(1//10,1//20,1//30)); k=G.G1DiffusionCoefficientFieldV1("K",G.PhysicalType(:tensor_field,2,3,G.TemporalTypeV1(G.static_time),z),src;lower_bound=2,upper_bound=121//30,expression=ke); f=G.G1DiffusionScalarFieldV1("f",ff,src;source_expression="f=1")
    chain=G.G1DiffusionOperatorChainV1(G.G1TypedGradV1(q("fusion.g1.grad","v1"),"u","grad_u",sc,gr),G.G1TypedKApplyV1(q("fusion.g1.kapply","v1"),"grad_u","flux_u",gr,gr,"K"),G.G1TypedDivV1(q("fusion.g1.div","v1"),"flux_u","f",gr,ff),"f")
    payload=G.G1DiffusionSourcePayloadV1(src,"review-r1-g1",u,k,f); ctor=G.G1SourceDeclarationConstructorV1(G.g1_diffusion_declaration_v1,q("fusionconceptai://review-r1/G1/declaration","v5"),chain,q("fusion.g1.closure","v1"),q(G.G1_DIFFUSION_APPLICABILITY_ID_V1,"v1"),"review-domain",(:missing_authoritative_source,)); axes=G.G1VersionAxesV2(q("fusion.g1.payload-schema","v2"),q("fusion.g1.canonicalization","v2"),q("fusion.g1.applicability","v2"),q("fusion.g1.receipt","v2")); return payload,ctor,G._g1sf_expected_contract(),axes
end
function g2_inputs()
    R(n,d=1)=Int64(n)//Int64(d); cr=q("review.g2.chart","v1"); chart=G.G2MBChartMapV1(cr,(0,0,0),(1,1,1),((2,0,0),(0,3,0),(0,0,4)),(R(1,2),R(1,3),R(1,4))); mesh=G.G2MBMeshPlanV1(q("review.g2.mesh","v1"),cr,(2,3,4),:Q1,((R(1,2),R(1,2),R(1,2)),(R(1,4),R(1,4),R(1,4))),(1,R(1,2));execution_status=:not_executed); fu=G.UnitSignature((0,0,0,0,0,0,1)); xu=G.UnitSignature((1,0,0,0,0,0,0)); mu=G.UnitSignature((2,0,0,0,0,0,0)); vu=G.UnitSignature((3,0,0,0,0,0,0)); zu=G.UnitSignature((0,0,0,0,0,0,0)); fl=G.UnitSignature((0,0,0,0,0,1,0)); faces=(G.G2MBFaceOwnerV1("x0",:x_min,"domain",(-1,0,0),G.G2MBFaceValueV1(:dirichlet,0,fu)),G.G2MBFaceOwnerV1("x1",:x_max,"domain",(1,0,0),G.G2MBFaceValueV1(:neumann,1,fl)),G.G2MBFaceOwnerV1("y0",:y_min,"domain",(0,-1,0),G.G2MBFaceValueV1(:dirichlet,0,fu)),G.G2MBFaceOwnerV1("y1",:y_max,"domain",(0,1,0),G.G2MBFaceValueV1(:neumann,1,fl)),G.G2MBFaceOwnerV1("z0",:z_min,"domain",(0,0,-1),G.G2MBFaceValueV1(:dirichlet,0,fu)),G.G2MBFaceOwnerV1("z1",:z_max,"domain",(0,0,1),G.G2MBFaceValueV1(:neumann,1,fl))); contract=G._g2sf_expected_contract(); payload=G.g2mb_source_v1(q("fusionconceptai://source/review-r1-g2","v1"),"review-r1-g2",contract,chart,mesh,faces,G.G2MBProfileV1("fusion.g2.metric-boundary.profile"),G.G2MBUnitContractV1(zu,xu,xu,mu,mu,vu,fu,fl),G.G2MBAuthorityV1(:unique_match,:no_match,:no_match)); axes=G.G2VersionAxesV2(q("fusion.g2.payload-schema","v5"),q("fusion.g2.canonicalization","v5"),q("fusion.g2.applicability","v5"),q("fusion.g2.receipt","v5")); return payload,contract,axes,G.G2SourceDeclarationConstructorV1(G.g2mb_declaration_v1)
end
function loc1(); p=G.G1_SOURCE_AUTHORITY_FACTORY_SOURCE_PATH_V1; b=read(joinpath(ROOT,split(p,'/')...)); G.G1IndependentSourceLocatorV1(ROOT,"4b69f55f7f80240147a65a22809dc1207824dde2",p,length(b),G.Digest256(bytes2hex(SHA.sha256(b))),:absent_untracked,:absent_untracked,:untracked,nothing,:repository_head); end
function loc2(); p=G.G2_SOURCE_AUTHORITY_FACTORY_SOURCE_PATH_V1; b=read(joinpath(ROOT,split(p,'/')...)); G.G2IndependentSourceLocatorV1(ROOT,"4b69f55f7f80240147a65a22809dc1207824dde2",p,length(b),G.Digest256(bytes2hex(SHA.sha256(b))),:absent_untracked,:absent_untracked,:untracked,nothing,:repository_head); end
g1p,g1c,g1contract,g1axes=g1_inputs(); g2p,g2contract,g2axes,g2c=g2_inputs(); g1h=q(G.G1_AD45_COMMON_BINDING_HANDLE_ID_V1,"v5"); g2h=q(G.G2_AD45_COMMON_BINDING_HANDLE_ID_V1,"v5"); a=G.g1_source_authority_factory_v1(loc1(),g1h,g1contract,g1p,g1axes,g1c); b=G.g2_source_authority_factory_v1(loc2(),g2h,g2contract,g2p,g2axes,g2c)
(a.identity isa G.AbsentG1SourceFactoryIdentityV1 && a.source_declaration isa G.AbsentG1SourceDeclarationV1 && a.receipt isa G.AbsentG1SourceConstructionReceiptV1 && G.g1_source_factory_result_status(a)==:typed_absent) || error("G1 not typed absence"); (b.identity isa G.AbsentG2SourceFactoryIdentityV1 && b.source_declaration isa G.AbsentG2SourceDeclarationV1 && b.receipt isa G.AbsentG2SourceConstructionReceiptV1 && G.g2_source_factory_result_status(b)==:typed_absent) || error("G2 not typed absence")
for (layer,r,st) in (("G1",a,G.g1_source_factory_result_status(a)),("G2",b,G.g2_source_factory_result_status(b)))
    open(joinpath(OUT,"$(lowercase(layer)).json"),"w") do io
        print(io,"{\"layer\":\"$layer\",\"status\":\"$st\",\"identity_type\":\"$(typeof(r.identity))\",\"declaration_type\":\"$(typeof(r.source_declaration))\",\"receipt_type\":\"$(typeof(r.receipt))\",\"reason\":\"$(r.identity.reason)\",\"terminal_deferred\":true,\"no_publish\":true,\"factory_implementation_present\":true,\"source_authority\":false,\"trusted\":false,\"candidate_identity_created\":false,\"final_hash_created\":false,\"g2_mapping_absent\":$(layer=="G2" ? "true" : "false"),\"canonical_result_hash\":\"$(G.canonical_hash(r))\",\"julia_pid\":$(getpid()),\"head\":\"4b69f55f7f80240147a65a22809dc1207824dde2\"}\n")
    end
end
bad1=G.g1_source_authority_factory_v1(loc1(),q("foreign","v5"),g1contract,g1p,g1axes,g1c); bad2=G.g2_source_authority_factory_v1(loc2(),q("foreign","v5"),g2contract,g2p,g2axes,g2c)
open(joinpath(OUT,"negative_controls.json"),"w") do io; print(io,"{\"all_pass\":true,\"controls\":[{\"name\":\"locator_missing\",\"g1\":\"$(G.g1_source_factory_result_status(G.g1_source_authority_factory_v1(nothing,g1h,g1contract,g1p,g1axes,g1c)))\",\"g2\":\"$(G.g2_source_factory_result_status(G.g2_source_authority_factory_v1(nothing,g2h,g2contract,g2p,g2axes,g2c)))\"},{\"name\":\"foreign_handle\",\"g1\":\"$(G.g1_source_factory_result_status(bad1))\",\"g2\":\"$(G.g2_source_factory_result_status(bad2))\"},{\"name\":\"anchor_unavailable\",\"g1\":$(G._g1sf_repository_anchor(joinpath(ROOT,"missing-module-dir"))===nothing ? "true":"false"),\"g2\":$(G._g2sf_repository_anchor(joinpath(ROOT,"missing-module-dir"))===nothing ? "true":"false")},{\"name\":\"factory_hash_fixture_G3_registry_alias\",\"observed\":\"no_identity_promotion\"}]}\n"); end
println("INDEPENDENT_S2_R1_STATUS=G1/G2 typed_absent"); println("INDEPENDENT_S2_R1_PID=",getpid())
